import { get_expense_forms } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { update_expense_forms } from "@/graphql/mutations.js";
import OverlayComp from "@/components/OverlayComp.vue";
import FormConfiguration from "@/components/ExpensesManagement/ExpensePopups/FormConfiguration.vue";
import ExpenseFormView from "@/components/ExpensesManagement/ExpensePopups/ExpenseFormView.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  mixins: [get_all_org_users],
  components: {
    SnackBar,
    OverlayComp,
    FormConfiguration,
    ExpenseFormView
  },
  data() {
    return {
      addData: false,
      stepsSelected: [],
      rolesRM: false,
      loading: false,
      initiaorRM: null,
      initiaorCheck: null,
      initiator: null,
      teamMember: null,
      teamMemberSelected: "",
      SnackBarComponent: {},
      overlay: false,
      selectedData: [],
      flowSteps: [{
        selected: false,
        title: "Initiator"
      }, {
        selected: false,
        title: "Initiator's Reporting Manager"
      }, {
        selected: false,
        title: "Roles"
      }],
      finalArray: [],
      addedRecords: [],
      listSelected: [],
      roleSelected: "",
      itemSelIndex: 0,
      userList: [],
      workflowList: [],
      formObject: {},
      inputRecords: [],
      tableData: {},
      templete: [],
      search: "",
      step: 1,
      addedFlowSteps: [],
      queryCheck: false,
      templateSteps: {},
      radiobutton: null,
      expenseHead: null,
      startCheck: false
    };
  },
  async created() {
    this.$store.commit("Setnamesearch", "");
    this.overlay = true;
    await this.get_all_org_users();
    await this.fetch_users();
    await this.get_initiated_expense();
  },
  watch: {
    addData: {
      async handler() {
        await this.get_all_org_users();
      }
    },
    teamMemberSelected: {
      handler(newValue) {
        if (newValue && this.radiobutton === "teamMember") {
          this.fetch_selected_data(newValue, "teamMember");
        }
      }
    }
  },
  methods: {
    save_next_step() {
      this.addedFlowSteps = this.addedRecords;
      // console.log(this.addedRecords);
      localStorage.setItem("flowSteps1Info", JSON.stringify(this.addedRecords));
      this.step = 2;
    },
    fetch_users() {
      this.userList = [];
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT") {
          this.userList.push({
            title: element.full_user_name,
            value: element.user_id
          });
        }
      });
      this.userList.sort((a, b) => a.title.localeCompare(b.title));
    },
    save_mutation(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
      this.step = 1;
      this.get_initiated_expense();
      // if (this.$refs.form) {
      //   this.$refs.form.reset();
      //   this.$refs.form.resetValidation && this.$refs.form.resetValidation();
      // }
    },
    fetchclear() {
      this.expenseHead = null;
      this.initiator = null;
      // Don't clear initiator when team member is selected
      // this.initiator = null;
    },
    fetch_selected_data(value, type) {
      this.inputRecords = [];
      if (type == "teamMember") {
        if (value && value.title) {
          this.inputRecords.push({
            step_no: this.addedRecords.length + 1,
            name: value.title,
            user_id: value.value,
            user_type: "team_member",
            workflow_template: this.templete
          });
        }
        this.expenseHead = null;
        this.initiator = null;
      } else if (type == "expense") {
        this.inputRecords.push({
          step_no: this.addedRecords.length + 1,
          name: "Group Head",
          user_id: "N/A",
          user_type: "expense_group",
          workflow_template: this.templete
        });
        this.radiobutton = null;
        this.teamMemberSelected = "";
        this.initiator = null;
      } else if (type == "initator") {
        this.inputRecords.push({
          step_no: this.addedRecords.length + 1,
          name: "Initiator",
          user_id: "N/A",
          user_type: "initator",
          workflow_template: this.templete
        });
        this.radiobutton = null;
        this.teamMemberSelected = "";
        this.expenseHead = null;
      }
      // console.log(value);
    },
    error_msg(value) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: value,
        timeout: 5000,
        Top: true
      };
    },
    previous_step() {
      this.step = 1;
    },
    delete_record(val) {
      this.addedRecords.splice(val, 1);
      let transformedArray = this.addedRecords.map((item, index) => {
        return {
          ...item,
          step_no: index + 1
        };
      });
      this.addedRecords = transformedArray;
      this.stepsSelected = [];
      this.radiobutton = null;
      this.expenseHead = null;
      this.teamMemberSelected = "";
    },
    close_dialog() {
      this.addData = false;
      this.initiaorRM = null;
      this.initiaorCheck = null;
      this.rolesRM = false;
      this.roleSelected = "";
      this.inputRecords = [];
      if (this.$refs.form) {
        this.$refs.form.reset();
        this.$refs.form.resetValidation && this.$refs.form.resetValidation();
      }
    },
    add_row(value) {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.itemSelIndex = value;
      this.addData = true;
    },
    add_dialog() {
      this.inputRecords = [];
      this.teamMember = null;
      this.initiaorCheck = null;
      this.initiaorRM = null;
      this.startCheck = true;
      this.addData = true;
    },
    async add_items() {
      var newArray = this.addedRecords;
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid && (this.radiobutton != null || this.expenseHead != null || this.initiator != null) && this.inputRecords.length > 0 && !this.isNameAlreadyExists(this.inputRecords[0].name)) {
        if (this.startCheck == true) {
          this.addedRecords.unshift(this.inputRecords[0]);
        } else {
          newArray.splice(this.itemSelIndex + 1, 0, this.inputRecords[0]);
          this.addedRecords = newArray;
        }
        let transformedArray = this.addedRecords.map((item, index) => {
          return {
            ...item,
            step_no: index + 1
          };
        });
        this.addedRecords = transformedArray;
        this.addData = false;
        this.radiobutton = null;
        this.expenseHead = null;
        this.startCheck = false;
        this.initiator = null;
        this.teamMemberSelected = "";
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: this.inputRecords.length === 0 ? "Please select a valid option" : "Data Already Exists",
          timeout: 5000,
          Top: true
        };
      }
    },
    isNameAlreadyExists(exitsName) {
      // console.log(this.addedRecords.some((obj) => obj.name === exitsName));
      return this.addedRecords.some(obj => obj.name === exitsName);
    },
    get_input(index) {
      this.inputRecords = [];
      if (index == 2 && index != undefined) {
        if (this.teamMemberSelected && this.teamMemberSelected.title) {
          this.inputRecords.push({
            step_no: this.addedRecords.length + 1,
            name: this.teamMemberSelected.title,
            user_id: this.teamMemberSelected.value,
            user_type: "team_member",
            workflow_template: this.templete
          });
        }
        this.teamMember = "member_team";
        this.initiaorCheck = null;
        this.initiaorRM = null;
        this.rolesRM = false;
      }
      this.finalArray = this.inputRecords;
    },
    async get_initiated_expense() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_expense_forms, {
          input: {
            user_email_id: data.user.user_email_id,
            organization_id: data.organization.organization_id
          }
        }));
        var response = JSON.parse(result.data.get_expense_forms);
        this.overlay = false;
        this.tableData = {};
        // console.log(response);
        if (response.Status == "SUCCESS") {
          // console.log(response);
          this.templete = response.data[0].workflow_template;
          this.templateSteps = response.data[0];
          this.tableData = response.data[0];
          this.addedRecords = this.tableData.workflow_approval_steps;

          // if (this.addedRecords.length > 0) {
          //   for (let s = 0; s < this.addedRecords.length; s++) {
          //     if (this.addedRecords[s].user_type == "team_member") {
          //       let name = this.orgUsers.filter(
          //         (x) => x.user_id == this.addedRecords[s].user_id
          //       );

          //       this.addedRecords[s].name =
          //         name.length > 0 ? name[0].full_user_name : "N/A";
          //     }
          //   }
          // }
          // console.log(this.addedRecords);
          this.queryCheck = true;
        } else {
          this.tableData = {};
          this.overlay = false;
        }
      } catch (error) {
        this.overlay = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
